(() => {
  'use strict';

  const data = window.COMPETENCY_MAP_DATA;
  if (!data || !Array.isArray(data.groups)) return;

  const findGroup = id => data.groups.find(group => group.id === id);
  const appendSkill = (groupId, id, title, level, note) => {
    const group = findGroup(groupId);
    if (!group || !Array.isArray(group.items) || group.items.some(item => item.id === id)) return;
    group.items.push({
      id,
      title,
      baselineLevel: level,
      description: `Нужно уметь уверенно выполнять навык «${title}», объяснять ход решения и проверять результат.`,
      diagnosis: `Объяснить правило по теме «${title}» и выполнить короткую проверку без подсказки.`,
      evidence: {
        date: '15.09.26',
        text: `Занятие: ${note}`,
        href: '15.09.26.html',
        texHref: '../tex_docs/15.09.26.tex'
      }
    });
  };

  // Два содержательных навыка урока отсутствовали в исходной сетке карты.
  // Добавляем их в ближайшие тематические сектора, сохраняя существующие id.
  appendSkill('arith', 'arith_21', 'Среднее арифметическое нескольких чисел', 3,
    'среднее арифметическое найдено как сумма всех чисел, делённая на их количество; использована удобная группировка слагаемых.');
  appendSkill('word', 'word_19', 'Средняя скорость на всём пути', 3,
    'средняя скорость найдена как весь путь, делённый на всё время, с переводом минут в часы.');

  const byId = new Map(
    data.groups.flatMap(group => (group.items || []).map(item => [item.id, item]))
  );
  const practiced = new Set();

  const setLesson = (id, level, note) => {
    const item = byId.get(id);
    if (!item) return;
    item.baselineLevel = Math.max(Number(item.baselineLevel) || 0, level);
    item.evidence = {
      date: '15.09.26',
      text: `Занятие: ${note}`,
      href: '15.09.26.html',
      texHref: '../tex_docs/15.09.26.tex'
    };
    practiced.add(id);
  };

  // Десятичные дроби.
  setLesson('dec_01', 4, 'уверенно повторены разряды десятичной дроби: десятые, сотые, тысячные и десятитысячные.');
  setLesson('dec_08', 4, 'закреплено дописывание нулей справа без изменения значения числа.');
  setLesson('dec_09', 4, 'сложение десятичных дробей выполнялось с выравниванием по запятой.');
  setLesson('dec_10', 4, 'вычитание десятичных дробей выполнялось с выравниванием по запятой и дописыванием нулей.');
  setLesson('dec_12', 3, 'повторён алгоритм умножения десятичных дробей и постановка запятой по числу десятичных знаков.');
  setLesson('dec_13', 3, 'повторено деление десятичной дроби на натуральное число столбиком.');

  // Обыкновенные дроби.
  setLesson('frac_base_05', 3, 'закреплена структура смешанного числа: целая и дробная части.');
  setLesson('frac_base_07', 3, 'неправильная дробь переводилась в смешанное число делением числителя на знаменатель с остатком.');
  setLesson('frac_base_11', 3, 'сокращение дробей выполнялось через общий множитель числителя и знаменателя.');
  setLesson('frac_ops_03', 3, 'сложение дробей с разными знаменателями повторено через общий знаменатель.');
  setLesson('frac_ops_04', 3, 'вычитание дробей с разными знаменателями повторено на нескольких примерах.');
  setLesson('frac_ops_08', 3, 'умножение дробей повторено как произведение числителей и знаменателей.');
  setLesson('frac_ops_11', 3, 'деление дробей закреплено как умножение на обратную вторую дробь.');

  // Вычислительная организация и среднее арифметическое.
  setLesson('arith_16', 3, 'использована удобная группировка слагаемых: пары 4,9+5,1 и 4,8+5,2 дают круглые суммы.');
  setLesson('arith_21', 3, 'среднее арифметическое вычислялось как сумма всех чисел, делённая на количество чисел.');

  // Неизвестные компоненты и буквенная модель.
  setLesson('eq_01', 3, 'неизвестное число обозначалось буквой x или y при переводе условия на математический язык.');
  setLesson('eq_03', 3, 'неизвестное слагаемое находилось вычитанием известного слагаемого из суммы.');
  setLesson('eq_04', 3, 'повторена связь уменьшаемого, вычитаемого и разности.');
  setLesson('eq_05', 3, 'неизвестное вычитаемое находилось как уменьшаемое минус разность.');
  setLesson('eq_06', 3, 'неизвестный множитель находился делением произведения на известный множитель.');
  setLesson('eq_07', 3, 'неизвестное делимое находилось умножением делителя на частное.');
  setLesson('eq_08', 2, 'неизвестный делитель разобран по формуле: делимое делится на частное; этому навыку нужна дополнительная автоматизация.');
  setLesson('eq_10', 3, 'составлялись числовые выражения по условию и по структуре формулы.');
  setLesson('eq_11', 3, 'словесные связи «больше/меньше на» и «больше/меньше в раз» переводились в буквенные выражения.');

  // Текстовые задачи, движение и единицы.
  setLesson('word_02', 3, 'в задачах выделялись известные и неизвестные величины.');
  setLesson('word_05', 3, 'задача на движение была представлена схемой из последовательных участков пути.');
  setLesson('word_06', 3, 'разобрана задача на скорость, время и расстояние с несколькими участками.');
  setLesson('word_08', 3, 'скорость находилась по общему расстоянию и общему времени.');
  setLesson('word_16', 3, 'ответ проверялся по смыслу единиц и исходному условию.');
  setLesson('word_19', 3, 'средняя скорость вычислялась по формуле весь путь / всё время.');
  setLesson('units_01', 3, 'метры переводились в километры делением на 1000.');
  setLesson('units_03', 3, 'минуты переводились в часы делением на 60.');
  setLesson('units_05', 3, 'закреплена единица скорости км/ч.');
  setLesson('units_06', 3, 'составная единица км/ч получена как километры, делённые на часы.');
  setLesson('units_07', 3, 'перед вычислением средней скорости время приводилось к единице, согласованной с требуемым ответом.');

  if (Array.isArray(data.repeatTopics)) {
    data.repeatTopics = data.repeatTopics.filter(id => !practiced.has(id));
    if (!data.repeatTopics.includes('eq_08')) data.repeatTopics.push('eq_08');
  }

  data.meta.studentName = 'Ксения Васильченко';
  data.meta.updated = '15.09.2026';
  data.meta.sourceNote = 'Карта учитывает входную диагностику 06.09.26 и занятия 08.09.26, 10.09.26 и 15.09.26. На последнем занятии повторены десятичные и обыкновенные дроби, среднее арифметическое, связи между компонентами действий, перевод текста в уравнение, средняя скорость и перевод единиц. Уровень 4 — уверенное выполнение; уровень 3 — содержательно отработано; уровень 2 — навык понятен, требуется автоматизация; уровень 0–1 — тема ещё не подтверждена.';
  data.meta.material = {
    title: 'Дроби, среднее арифметическое, уравнения и средняя скорость',
    date: '15.09.26',
    pdf: '../pdf_docs/15.09.26.pdf',
    tex: '../tex_docs/15.09.26.tex'
  };

  const slug = value => String(value).toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/[^a-z0-9а-я]+/gi, '-')
    .replace(/^-+|-+$/g, '');

  // Один раз сбрасываем пользовательский кэш прежней базы, чтобы обновление 15.09.26
  // сразу появилось на карте; последующие ручные изменения снова сохраняются.
  const markerKey = `${data.meta.student}-competency-map-lesson-20260915-v1`;
  try {
    if (!localStorage.getItem(markerKey)) {
      const baseKey = `${data.meta.student}-${slug(data.meta.program)}`;
      localStorage.removeItem(`${baseKey}-competency-map`);
      localStorage.removeItem(`${baseKey}-repeat`);
      localStorage.setItem(markerKey, '1');
    }
  } catch (_) {}
})();
